#if UNITY_EDITOR
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEngine.EventSystems;
using UnityEngine.UI;

public static class PileBoundaryPresentationValidation
{
 public static bool Running{get;private set;}
 public static string Output{get;private set;}
 static bool typographyOnly;
 [Serializable] class Result{public string folder,status;}
 static void Check(bool b,string m){if(!b)throw new Exception(m);}
 static ForgeSeatView Read(string test,string label,int seat){var paths=Directory.GetFiles(".tools/pile-boundaries-1007/native/"+test,"result.json",SearchOption.AllDirectories).Select(p=>JsonUtility.FromJson<Result>(File.ReadAllText(p))).Where(r=>r.status=="PASS").ToArray();Check(paths.Length==1,"Ambiguous producer "+test);string p=paths[0].folder+"/"+label+"-seat"+seat+".json",rp=paths[0].folder+"/"+label+"-request.json",name=test+"-"+label+"-seat"+seat;var v=JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p));v.request=JsonUtility.FromJson<ForgeRequest>(File.ReadAllText(rp));Check(v.request.seat==seat,"Request attached to wrong recipient");if(!File.Exists(Output+"/inputs/"+name+".json")){File.Copy(p,Output+"/inputs/"+name+"-raw.json");File.Copy(rp,Output+"/inputs/"+name+"-request.json");File.WriteAllText(Output+"/inputs/"+name+".json",JsonUtility.ToJson(v,true));File.AppendAllText(Output+"/inputs.tsv",name+"\t"+p+"\t"+rp+"\n");}return v;}
 static IEnumerator Frame(){yield return new WaitForEndOfFrame();yield return null;Canvas.ForceUpdateCanvases();}
 static void Click(Button b){Canvas.ForceUpdateCanvases();var e=new PointerEventData(EventSystem.current){position=RectTransformUtility.WorldToScreenPoint(null,b.transform.TransformPoint(((RectTransform)b.transform).rect.center)),button=PointerEventData.InputButton.Left};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(e,hits);Check(b.interactable&&hits.Count>0&&hits[0].gameObject.GetComponentInParent<Button>()==b,"Pile ray blocked "+b.name);ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,ExecuteEvents.pointerClickHandler);}
 public static void Run(bool typography=false){Check(Application.isPlaying&&!Running,"Play required/already running");typographyOnly=typography;var ui=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldController>()??new GameObject("PileBoundaryValidation").AddComponent<ForgeBattlefieldController>();Running=true;Output=".tools/pile-boundaries-1007/ui/"+DateTime.UtcNow.ToString("yyyyMMddTHHmmssfffffffZ");Directory.CreateDirectory(Output+"/inputs");Directory.CreateDirectory(Output+"/sources");File.WriteAllText(Output+"/result.txt","RUNNING");File.WriteAllText(".tools/pile-boundaries-1007/ui/latest.txt",Output);foreach(string p in new[]{"Assets/Scripts/Editor/PileBoundaryPresentationValidation.cs","Assets/Scripts/UI/ForgeBattlefieldController.Piles.cs"})File.Copy(p,Output+"/sources/"+Path.GetFileName(p));ui.StartCoroutine(Guard(ui));}
 static IEnumerator Guard(ForgeBattlefieldController ui){var tasks=new Stack<IEnumerator>();tasks.Push(Validate(ui));try{while(tasks.Count>0){object next;try{var t=tasks.Peek();if(!t.MoveNext()){tasks.Pop();continue;}next=t.Current;}catch(Exception e){Running=false;File.WriteAllText(Output+"/result.txt","FAIL "+e);throw;}if(next is IEnumerator nested)tasks.Push(nested);else yield return next;}File.WriteAllText(Output+"/result.txt",typographyOnly?"PASS: six actual known-face/opposing-private pile cells across three locales after header row-height change: first-render title/instruction/count glyphs and preferred-height bounds, fixed fonts, whole-pile rays/native indexes/stale/duplicate/readonly guards. Earlier23 consumer cells remain separate evidence; no native tests rerun.":"PASS: actual predefined piles in three locales: own known face-down faces, opposing private backs/public faces, empty piles, explicit whole-pile ray choice/confirmation, native indexes, fixed fonts and stale/duplicate/readonly guards. Existing visible/one-hidden/both-hidden/mixed-owner pile consumers and multi/left-right picker confirmation sampled as increments; native outcomes independent.");}finally{while(tasks.Count>0)(tasks.Pop() as IDisposable)?.Dispose();Running=false;}}
 static IEnumerator Pile(ForgeBattlefieldController ui,ForgeSeatView v,string label,int choice)
 {
  int calls=0,last=-1;Action<int> submit=i=>{calls++;last=i;};ui.Present(null,v.seat,false,null,null,"");ui.Present(v,v.seat,true,submit,null,"");yield return Frame();var menu=GameObject.Find("PileSelection");Check(menu!=null,"Pile menu missing "+label);Button Find(string name)=>menu.GetComponentsInChildren<Button>().Single(b=>b.name==name);
  Check(!Find("PileConfirm").interactable&&menu.GetComponentsInChildren<Button>().Length==3,"Not whole-pile explicit choice");var fonts=menu.GetComponentsInChildren<Text>().Select(t=>t.fontSize).ToArray();Check(menu.GetComponentsInChildren<Text>().All(t=>!t.resizeTextForBestFit),"Autofit pile text");
  if(typographyOnly)foreach(var t in menu.GetComponentsInChildren<Text>().Where(t=>t.name=="Title"||t.name=="Instruction"||t.name=="Count"))Check(t.preferredHeight<=t.rectTransform.rect.height+2&&!t.canvasRenderer.cull&&t.cachedTextGenerator.vertexCount>0,"Pile header clipped: "+t.name+" "+t.preferredHeight+"/"+t.rectTransform.rect.height);
  foreach(var pile in v.request.piles){var content=menu.transform.Find("Pile_"+pile.pileId+"/PileScroll/Content");var images=content.GetComponentsInChildren<Image>().Where(i=>i.name.StartsWith("PileCard_")).ToArray();Check(images.Length==(pile.concealed?0:pile.cardCount),"Pile face count");foreach(var c in pile.cards??Array.Empty<ForgeCardView>()){var image=images.Single(i=>i.name=="PileCard_"+c.id);Check(image.sprite!=null,"Pile image missing");bool known=c.faceDown&&!string.IsNullOrEmpty(c.knownFacePrintingKey);string name=known?c.knownFaceName:c.name;Check(image.transform.Find("CardName").GetComponent<Text>().text==GamePreferences.CardFaceName(name),"Wrong known face name");if(known){CardImageLibrary.TryLoadPrintingKey(c.knownFacePrintingKey,out var expected);Check(expected!=null&&image.sprite==expected,"Known exile preview is still card back");}else if(c.faceDown){CardImageLibrary.TryLoadCardBack(out var expected);Check(expected!=null&&image.sprite==expected,"Private pile face exposed");}}
  }
  ui.Choose(choice,v.request.requestId-1);Check(calls==0,"Stale pile submitted");Click(Find("SelectPile_"+choice));Check(calls==0&&Find("PileConfirm").interactable,"Pile submitted without confirm");ui.Present(v,v.seat,true,submit,null,"");yield return Frame();Check(fonts.SequenceEqual(menu.GetComponentsInChildren<Text>().Select(t=>t.fontSize)),"Pile font changed");ScreenCapture.CaptureScreenshot(Output+"/"+GamePreferences.Language+"-"+label+".png");yield return new WaitForSecondsRealtime(.15f);Click(Find("PileConfirm"));ui.Choose(choice,v.request.requestId);Check(calls==1&&last==choice,"Pile index/duplicate mismatch");ui.Present(v,v.seat,false,submit,null,"");yield return Frame();ui.Choose(choice,v.request.requestId);Check(calls==1&&menu.GetComponentsInChildren<Button>().All(b=>!b.interactable),"Readonly pile submitted");File.AppendAllText(Output+"/steps.log",GamePreferences.Language+" "+label+" PASS\n");
 }
 static IEnumerator Validate(ForgeBattlefieldController ui)
 {
  string locale=GamePreferences.Language;bool enabled=ui.enabled;ui.enabled=false;var migration=UnityEngine.Object.FindFirstObjectByType<ForgeBattlefieldMigrationNotice>();bool me=migration!=null&&migration.enabled;if(migration!=null)migration.enabled=false;var module=EventSystem.current.currentInputModule;bool ie=module!=null&&module.enabled;if(module!=null)module.enabled=false;
  try{foreach(string language in new[]{"zh-CN","en-US","ja-JP"}){int revision=GamePreferences.Revision;bool change=GamePreferences.Language!=language;GamePreferences.SetLanguage(language);float until=Time.realtimeSinceStartup+12;while((!GamePreferences.Ready||change&&GamePreferences.Revision==revision)&&Time.realtimeSinceStartup<until)yield return null;Check(GamePreferences.Ready,"Locale not ready");
   var samples=typographyOnly?new[]{("hostile-left-hidden","pile-1",1,0),("hostile-left-hidden","pile-2",2,1)}:new[]{("hostile-left-hidden","pile-1",1,0),("hostile-left-hidden","pile-2",2,1),("hostile-right-visible","pile-2",2,1),("hostile-empty","pile-1",1,0),("abstract-hidden","pile-1",2,0)};
   foreach(var s in samples)yield return Pile(ui,Read(s.Item1,s.Item2,s.Item3),s.Item1+"-"+s.Item2,s.Item4);
   if(language=="zh-CN"&&!typographyOnly){
    foreach(string old in new[]{"fof-left","favor-hidden","portal-left","parley-right"}){string p="Tools/Validation/Reports/Piles/"+old+"-choice.json";File.Copy(p,Output+"/inputs/legacy-"+old+".json");File.AppendAllText(Output+"/inputs.tsv","legacy-"+old+"\t"+p+"\n");yield return Pile(ui,JsonUtility.FromJson<ForgeSeatView>(File.ReadAllText(p)),"legacy-"+old,0);}
    foreach(var s in new[]{("whims-balanced","split-1-1",1),("whims-empty","split-2-1",2),("river-piles","river-split-1",1),("river-piles","river-split-2",2)}){
     var v=Read(s.Item1,s.Item2,s.Item3);int calls=0,last=-1;ui.Present(null,v.seat,false,null,null,"");ui.Present(v,v.seat,true,i=>{calls++;last=i;},null,"");yield return Frame();int index=Array.FindIndex(v.request.options,o=>o.id=="ok");Check(index>=0,"Native split confirm missing");var buttons=UnityEngine.Object.FindObjectsByType<Button>(FindObjectsSortMode.None).Where(b=>b.gameObject.activeInHierarchy).ToArray();var b=buttons.FirstOrDefault(x=>x.name=="SelectionAction_"+index)??buttons.FirstOrDefault(x=>x.name=="SkipCombatButton");Check(b!=null,"No native split confirmation: "+string.Join(",",buttons.Select(x=>x.name)));Click(b);Check(calls==1&&last==index,"Wrong split confirm");File.AppendAllText(Output+"/steps.log",language+" "+s.Item1+" "+s.Item2+" PASS\n");
    }
   }
  }}finally{ui.Present(null,1,false,null,null,"");ui.enabled=enabled;if(migration!=null)migration.enabled=me;if(module!=null)module.enabled=ie;GamePreferences.SetLanguage(locale);}
 }
}
#endif
